import {ageDecision} from './age100.mjs';
import model from './initial-profiles.mjs';
import {questions,byId,featureLabels,domainDefs,validAnswer,sanitizeAnswers,answerLabel} from './data100.mjs';
export {model};
const scales={E:[[1,6,11,16],[6,16]],A:[[2,7,12,17],[7,17]],C:[[3,8,13,18],[8,18]],N:[[4,9,14,19],[9,19]],I:[[5,10,15,20],[10,15,20]],avoidance:[[21,22,23,24,25,26],[21,22,23,24]],anxiety:[[27,28,29],[]]};
const active=Object.keys(model.weights),own=o=>Object.prototype.hasOwnProperty.call(o??{},'x');
const known=v=>v!==undefined&&v!==null&&v!=='unknown'&&v!=='any';
const clamp=(n,a=0,b=1)=>Math.min(b,Math.max(a,n));
export function profileFromAnswers(input){const a=sanitizeAnswers(input),f={};for(const [key,[ids,rev]] of Object.entries(scales)){f[key]=ids.every(id=>typeof a[id]==='number')?(ids.reduce((s,id)=>s+(rev.includes(id)?6-a[id]:a[id]),0)/ids.length-1)*25:null;}for(let id=30;id<=60;id++)f['q'+id]=known(a[id])?a[id]:null;return f;}
export function featureDistance(key,a,b){if(key==='q40'){const A=new Set(a),B=new Set(b),union=new Set([...A,...B]);return union.size?1-[...A].filter(x=>B.has(x)).length/union.size:0;}if(['q44','q45','q53'].includes(key))return Number(a!==b);return Math.abs(a-b)/(key.startsWith('q')?4:100);}
export function classifyAnswers(a){return classifyProfile(profileFromAnswers(a));}
export function classifyProfile(f){const usable=active.filter(k=>known(f[k])),coverage=usable.reduce((s,k)=>s+model.weights[k],0),groupsPresent=Object.values(model.groups).filter(keys=>keys.some(k=>usable.includes(k))).length;if(coverage+1e-10<.8||groupsPresent<6)return {status:'insufficient',primary:null,ranking:[],coverage,groupsPresent,features:f};const ranking=model.prototypes.map(p=>{const distance=usable.reduce((s,k)=>s+model.weights[k]*featureDistance(k,f[k],p.features[k]),0)/coverage;return {...p,distance,fit:100*(1-distance)}}).sort((a,b)=>a.distance-b.distance||a.type.localeCompare(b.type));const tied=ranking.filter(p=>Math.abs(p.distance-ranking[0].distance)<=1e-10);const gap=ranking[0].fit-ranking[1].fit;return {features:f,ranking,coverage,groupsPresent,gap,tied,primary:tied.length===1?ranking[0]:null,status:tied.length>1?'tied':gap<=3?'borderline':'assigned'};}
const traitKeys=['E','A','C','I'];
const targetFeature=id=>id<=64?traitKeys[id-61]:'q'+(id-35);
const domainFor=id=>domainDefs.find(d=>d.ids.includes(id));
const qForFeature=k=>k.startsWith('q')?Number(k.slice(1)):null;
function intervalFit(x,low,high,min,max){low=clamp(low,min,max);high=clamp(high,min,max);if(low===min&&high===max)return null;const d=Math.max(low-x,0,x-high),M=Math.max(low-min,max-high);return M?clamp(1-d/M):null;}
export function wishFit(id,wish,actual,tolerance='some'){if(!known(wish))return null;if(!known(actual))return null;if(id<=64){const span={close:0,some:10,wide:20}[tolerance]??10,bands={low:[0,40],mid:[30,70],high:[60,100]},band=bands[wish];return band?intervalFit(actual,band[0]-span,band[1]+span,0,100):null;}const self=byId[id-35],numeric=self.options.every(o=>typeof o.value==='number');if(numeric){const t={close:0,some:1,wide:2}[tolerance]??1;return intervalFit(actual,id===89?1:wish-t,wish+t,1,5);}const allowed=Array.isArray(wish)?wish:[wish],actualValues=Array.isArray(actual)?actual:[actual];if(id===87){const specified=actualValues.filter(x=>x!=='irregular'),want=allowed.filter(x=>x!=='irregular');if(!specified.length||!want.length)return null;return Number(specified.some(x=>want.includes(x)));}return Number(actualValues.some(x=>allowed.includes(x)));}
export function direction(a,b,ageA=null,ageB=null){const f=profileFromAnswers(b),rows=[],excluded=[],unresolved=[];for(const flag of Array.isArray(a[97])?a[97]:[]){if(flag==='age'){const status=ageDecision(ageA,ageB);if(status==='excluded')excluded.push(flag);if(status==='unresolved')unresolved.push(flag);continue;}const id=({smoking:90,children:93,religion:91,tattoo:95})[flag],k=targetFeature(id),wish=a[id],actual=f[k];if(!known(wish)||!known(actual)){unresolved.push(flag);continue;}if(!Array.isArray(wish)||!wish.includes(actual))excluded.push(flag);}
 let informative=0,observed=0;for(let id=61;id<=95;id++){const wish=a[id],feature=targetFeature(id);if(!known(wish))continue;const numeric=id>64&&byId[id-35].options.every(o=>typeof o.value==='number');if(numeric){const r={close:0,some:1,wide:2}[a[98]]??1;if((id===89?1:Math.max(1,wish-r))===1&&Math.min(5,wish+r)===5)continue;}informative++;let fit=wishFit(id,wish,f[feature],a[98]);if(id===87){const ownSlots=Array.isArray(a[52])?a[52].filter(x=>x!=='irregular'):[],otherSlots=Array.isArray(b[52])?b[52].filter(x=>x!=='irregular'):[];if(!ownSlots.length||!otherSlots.length)fit=null;else if(!ownSlots.some(x=>otherSlots.includes(x)))fit=0;}if(fit!==null){observed++;rows.push({id,feature,domain:domainFor(id).id,fit,wish,actual:f[feature],label:featureLabels[feature]});}}
 const domains=domainDefs.flatMap(d=>{const items=rows.filter(r=>r.domain===d.id);return items.length?[{...d,fit:items.reduce((s,r)=>s+r.fit,0)/items.length,weight:Array.isArray(a[96])&&a[96].includes(d.id)?2:1,items}]:[];});const coverage=informative?observed/informative:0;const score=domains.length?100*domains.reduce((s,d)=>s+d.fit*d.weight,0)/domains.reduce((s,d)=>s+d.weight,0):null;return {score,coverage,informative,observed,rows,domains,excluded,unresolved};}
export function pair(a,b,ageA=null,ageB=null){const ab=direction(a,b,ageA,ageB),ba=direction(b,a,ageB,ageA),score=ab.score===null||ba.score===null?null:ab.score+ba.score===0?0:2*ab.score*ba.score/(ab.score+ba.score);return {ab,ba,score,eligible:score!==null&&ab.coverage>=.7&&ba.coverage>=.7&&!ab.excluded.length&&!ba.excluded.length&&!ab.unresolved.length&&!ba.unresolved.length&&ab.score>=50&&ba.score>=50};}
function featureEvidence(a,ids){return ids.map(id=>({id,question:byId[id].text,answer:answerLabel(id,a[id])}));}
export function readings(a){const out=[];const add=(key,title,text,ids,priority=1)=>{if(ids.every(id=>known(a[id])))out.push({key,title,text,evidence:featureEvidence(a,ids),priority});};
 if(a[30]>=4&&a[32]<=2)add('expression','먼저 다가가지만, 좋아한다는 말은 자주 하지 않아요.','관계를 시작하는 행동과 말로 마음을 전하는 빈도가 다르게 나타났어요. 말 대신 어떤 행동으로 표현하는지 함께 이야기해볼 수 있어요.',[30,32],10);
 else if(a[32]>=4&&a[33]<=2)add('expression','애정 표현은 자주 하고, 개인적인 고민은 골라서 나눠요.','좋아한다는 말을 하는 것과 내 고민을 공개하는 것은 다르게 선택했어요. 이를 마음을 여는 속도라고 단정하지 않아요.',[32,33],10);
 else add('expression',a[32]>=4?'좋아하는 마음을 말로 전하는 편이에요.':a[32]<=2?'좋아하는 마음을 자주 말하는 편은 아니에요.':'애정 표현과 고민 공유를 상황에 맞춰 선택해요.',`말로 표현하는 빈도는 ‘${answerLabel(32,a[32])}’, 고민을 나누는 범위는 ‘${answerLabel(33,a[33])}’라고 답했어요.`,[32,33],3);
 if(a[42]>=4&&a[43]>=4)add('conflict','서운함은 빨리 이야기하고, 감정이 커지면 잠깐 쉬고 싶어요.','대화를 시작하는 시점과 대화 중 필요한 휴식은 별개예요. 잠시 멈출 때 다시 이야기할 시간을 정하면 기대를 맞추기 쉬워요.',[42,43],10);
 else if(a[42]<=2&&a[43]<=2)add('conflict','생각을 정리한 뒤, 시작한 대화는 이어가고 싶어요.','바로 말을 꺼내기보다 준비할 시간이 필요하고, 대화가 시작되면 계속 이야기하는 쪽을 골랐어요.',[42,43],9);
 else add('conflict','갈등 대화에서 시작 시점과 쉬는 방식이 중요해요.',`대화 시작은 ‘${answerLabel(42,a[42])}’, 감정이 올라왔을 때는 ‘${answerLabel(43,a[43])}’가 편하다고 답했어요.`,[42,43],3);
 if(a[38]>=4&&a[39]>=4)add('experience','새로운 곳에 가는 것을 좋아하고, 약속은 미리 준비해요.','경험의 새로움과 일정의 즉흥성은 같지 않아요. 새로운 장소를 탐색하면서 시간과 장소는 정해두는 쪽이에요.',[38,39],9);
 else add('experience',a[38]>=4?'만나기 전에 시간과 장소를 정해두는 편이에요.':a[38]<=2?'당일의 상황을 보며 약속을 정하는 편이에요.':'데이트의 계획과 장소를 유연하게 선택해요.',`약속 준비는 ‘${answerLabel(38,a[38])}’, 장소 선택은 ‘${answerLabel(39,a[39])}’라고 답했어요.`,[38,39],2);
 if(a[37]<=2&&a[32]>=4)add('time','각자 보내는 시간이 있어도 애정 표현은 자주 하고 싶어요.','함께 있는 시간의 비중과 마음을 표현하는 빈도를 다르게 선택했어요. 각자 시간을 보낸다는 이유로 마음이 적다고 해석하지 않아요.',[37,32],9);
 else add('time','연락하는 빈도와 만나는 빈도를 따로 정해요.',`연락은 ‘${answerLabel(34,a[34])}’, 만남은 ‘${answerLabel(36,a[36])}’를 골랐어요. 서로 단위가 다른 항목이므로 선택 단계의 차이로 선호를 단정하지 않아요.`,[34,36],1);
 add('support','상대가 힘들 때 내가 먼저 하는 일이 있어요.',`도움의 첫 반응은 ‘${answerLabel(45,a[45])}’, 다툰 뒤에는 ‘${answerLabel(44,a[44])}’를 선택했어요. 상대가 받고 싶은 방식도 확인해보면 좋아요.`,[45,44],2);
 const selected=[],used=new Set();for(const r of out.sort((x,y)=>y.priority-x.priority)){if(!used.has(r.key)){selected.push(r);used.add(r.key);}if(selected.length===3)break;}return selected;}
export function preferenceGaps(a){return Array.from({length:31},(_,i)=>i+65).flatMap(id=>{const actual=a[id-35],wish=a[id];if(!known(actual)||!known(wish))return [];const fit=wishFit(id,wish,actual,a[98]);return fit!==null&&fit<1?[{id,selfId:id-35,label:featureLabels['q'+(id-35)],self:answerLabel(id-35,actual),wish:answerLabel(id,wish),fit}]:[];}).sort((x,y)=>x.fit-y.fit).slice(0,2);}
function actualLabel(feature,value){return feature.startsWith('q')?answerLabel(qForFeature(feature),value):`${featureLabels[feature]} 표시 점수 ${Math.round(value)}`;}
function directReason(a,b,r,whose){const value=answerLabel(qForFeature(r.feature),r.actual);const wish=answerLabel(r.id,r.wish);const label=r.label;return {label,title:whose==='me'?`내가 원하는 ${label}과 맞는 점`:`상대가 원하는 ${label}과 맞는 점`,text:r.feature.startsWith('q')?(whose==='me'?`나는 ‘${wish}’를 원하고, 상대는 ‘${value}’라고 답했어요.`:`상대는 ‘${wish}’를 원하고, 나는 ‘${value}’라고 답했어요.`):`${whose==='me'?'내가 고른':'상대가 고른'} 성향 범위와 ${whose==='me'?'상대의':'나의'} 측정 점수가 맞아요.`,ids:[r.id,qForFeature(r.feature)].filter(Boolean),fit:r.fit};}
export function recommendationReasons(a,b,p){const priorities=Array.isArray(a[96])?a[96]:[],weight=r=>r.fit+(priorities.includes(r.domain)?.1:0);const me=p.ab.rows.filter(r=>r.fit>=.7).sort((x,y)=>weight(y)-weight(x))[0],them=p.ba.rows.filter(r=>r.fit>=.7&&(!me||r.feature!==me.feature)).sort((x,y)=>(y.fit+(Array.isArray(b[96])&&b[96].includes(y.domain)?.1:0)+(me&&y.domain!==me.domain?.05:0))-(x.fit+(Array.isArray(b[96])&&b[96].includes(x.domain)?.1:0)+(me&&x.domain!==me.domain?.05:0)))[0],diff=[...p.ab.rows.map(r=>({...r,side:'내 선호'})),...p.ba.rows.map(r=>({...r,side:'상대 선호'}))].filter(r=>r.fit<1).sort((x,y)=>x.fit-y.fit)[0];const all=[];if(me)all.push(directReason(a,b,me,'me'));if(them)all.push(directReason(a,b,them,'them'));if(diff)all.push({label:diff.label,title:'조율할 차이',text:`${diff.side}의 ${diff.label}에서는 선호 범위와 실제 응답이 달라요. 원하는 쪽은 ‘${answerLabel(diff.id,diff.wish)}’, 실제 응답은 ‘${actualLabel(diff.feature,diff.actual)}’예요.`,fit:diff.fit});if(a[100]==='adjust')all.sort((x,y)=>x.title==='조율할 차이'?-1:y.title==='조율할 차이'?1:0);else if(a[100]==='their_wishes')all.sort((x,y)=>x.title.startsWith('상대')?-1:y.title.startsWith('상대')?1:0);else if(a[100]==='common'){const r=p.ab.rows.find(r=>r.feature.startsWith('q')&&known(a[qForFeature(r.feature)])&&JSON.stringify(a[qForFeature(r.feature)])===JSON.stringify(b[qForFeature(r.feature)]));if(r)all[0]={label:r.label,title:'둘이 비슷하게 고른 점',text:`${r.label}에서 둘 다 ‘${answerLabel(qForFeature(r.feature),r.actual)}’를 골랐어요.`};}return all.slice(0,3);}
export function demoAnswers(type=model.prototypes[9].type,variant=0){const p=model.prototypes.find(p=>p.type===type)??model.prototypes[9],a={};for(const [key,[ids,rev]] of Object.entries(scales)){const target=p.features[key]??(key==='N'?40:key==='anxiety'?35:30);const sum=Math.round((1+target/25)*ids.length),base=Math.floor(sum/ids.length),extra=sum-base*ids.length;ids.forEach((id,i)=>{const value=clamp(base+(i<extra?1:0),1,5);a[id]=rev.includes(id)?6-value:value;});}for(let id=30;id<=60;id++){let v=p.features['q'+id];if(v==null)v=({48:3,49:'alternate',50:'experience',52:['afternoon','evening'],54:2,55:'none',56:'none',57:3,58:'undecided',60:'none'})[id]??3;a[id]=structuredClone(v);}if(variant){a[32]=a[32]<=2?5:1;a[42]=a[42]<=2?5:1;a[43]=a[43]<=2?5:1;}traitKeys.forEach((k,i)=>a[61+i]=(p.features[k]??50)<=40?'low':p.features[k]>=60?'high':'mid');for(let id=65;id<=95;id++){const val=a[id-35],self=byId[id-35];a[id]=self.options.every(o=>typeof o.value==='number')?val:Array.isArray(val)?structuredClone(val):[val];}a[96]=variant?['experience','conflict','boundaries']:['approach','connection','experience'];a[97]='any';a[98]='some';a[99]='fit';a[100]='my_wishes';return a;}
export function recommendations(a){const candidates=model.prototypes.map((p,i)=>{const answers=demoAnswers(p.type),score=pair(a,answers);return {id:'synthetic-'+i,type:p.type,korean:p.korean,answers,...score,reasons:recommendationReasons(a,answers,score)};}).filter(c=>c.eligible).sort((x,y)=>y.score-x.score||x.type.localeCompare(y.type));const selected=candidates.slice(0,3);if(a[99]==='diverse'&&selected.length===3&&new Set(selected.map(c=>c.type)).size<3){const alternative=candidates.find(c=>!selected.some(s=>s.type===c.type));if(alternative)selected[2]=alternative;}return {all:candidates,selected};}
export function missingSelf(a){return questions.filter(q=>q.id<=60&&(!validAnswer(q.id,a[q.id])||a[q.id]==='unknown'));}
